def stuck_epochs(losses, level=2.2):
    n = 0
    for v in losses:
        if v > level:
            n += 1
        else:
            break
    return n


def deep_vs_residual(curves):
    if curves['residual'][-1] < curves['plain'][-1]:
        return 'residual'
    return 'plain'

